export function clamp(n) {
  if (n > Number.MAX_SAFE_INTEGER) {
    throw new RangeError(`clamp: ${n} exceeds Number.MAX_SAFE_INTEGER; precision would be lost`);
  }
  return Math.max(0, n);
}

